package com.timachado.brothermatrizes.desktop

import com.timachado.brothermatrizes.desktop.platform.DesktopArchiveInventory
import com.timachado.brothermatrizes.desktop.platform.DesktopArchiveQuotaJournal
import java.nio.file.Files
import java.nio.file.Path

/**
 * Child JVM harness used ONLY by DesktopArchiveQuotaMultiprocessTest.
 * All folders are generated by the parent test; no backend, network or
 * app user library is ever accessed.
 *
 * A nonzero exit means that the safety property failed. Intentionally
 * uses Runtime.halt to simulate power/process loss without finally blocks.
 */
internal object DesktopArchiveQuotaProcessProbe {
    @JvmStatic
    fun main(args: Array<String>) {
        require(args.size == 2) { "Expected test command and sandbox directory." }
        val command = args[0]
        val root = Path.of(args[1]).toAbsolutePath().normalize()
        require(Files.isDirectory(root) && !Files.isSymbolicLink(root)) {
            "Only an existing temporary QA directory is allowed."
        }
        val journal = DesktopArchiveQuotaJournal(root)
        val item = DesktopArchiveInventory.Item(
            0, "QA/matriz.pes", "matriz.pes", "PES", 64,
            DesktopArchiveInventory.Category.MATRIX
        )
        when (command) {
            "hold-reservation" -> {
                journal.acquireLease().use {
                    val current = journal.begin(item)
                    check(current.stage == DesktopArchiveQuotaJournal.Stage.RESERVE_UNKNOWN)
                    Files.writeString(root.resolve(".child-ready"), "READY")
                    // The parent kills this process forcibly: no close/finally
                    // is allowed to remove or finalize the durable marker.
                    while (true) Thread.sleep(1_000)
                }
            }
            "probe-lock-held" -> {
                val refused = runCatching { journal.acquireLease().use { } }
                    .exceptionOrNull()
                check(refused is IllegalStateException &&
                    refused.message.orEmpty().contains("Outra instância")) {
                    "The second JVM acquired another JVM's file lock."
                }
            }
            "probe-surviving-reserve" -> {
                journal.acquireLease().use {
                    val pending = journal.listPending().single()
                    check(pending.stage == DesktopArchiveQuotaJournal.Stage.RESERVE_UNKNOWN)
                    check(pending.reservationKey == null)
                    val refused = runCatching { journal.begin(item) }.exceptionOrNull()
                    check(refused is IllegalStateException &&
                        refused.message.orEmpty().contains("reconciliação")) {
                        "Restart after process kill unexpectedly accepted another reserve."
                    }
                }
            }
            "force-exit-after-finalize-intent" -> {
                journal.acquireLease().use {
                    val opened = journal.begin(item)
                    val accepted = journal.reserved(
                        opened,
                        "usage_12345678-1234-1234-1234-123456789abc"
                    )
                    val current = journal.finalizing(accepted)
                    check(current.stage == DesktopArchiveQuotaJournal.Stage.FINALIZE_UNKNOWN)
                    // A hard stop must leave an unresolved marker; the
                    // server may already have completed finalization.
                    Runtime.getRuntime().halt(61)
                }
            }
            "probe-surviving-finalize" -> {
                journal.acquireLease().use {
                    val pending = journal.listPending().single()
                    check(pending.stage == DesktopArchiveQuotaJournal.Stage.FINALIZE_UNKNOWN)
                    check(pending.reservationKey ==
                        "usage_12345678-1234-1234-1234-123456789abc")
                    check(runCatching { journal.begin(item) }.exceptionOrNull()
                        is IllegalStateException) {
                        "An unresolved finalize incorrectly allowed another reserve."
                    }
                }
            }
            else -> error("Unsupported internal QA operation.")
        }
    }
}
